// src/components/Dashboard/ReleaseMaster.js
import React, { useMemo } from 'react';

/**
 * [PH1-F3] Embed the PPT directly with Office Web viewer.
 * NOTE: For local files, we generate an absolute URL to /files/PBPT RM - Master.pptx.
 * If you later switch to SharePoint, replace `localUrl` with the direct SP file URL
 * and Office will render it seamlessly (and can do edit if permissions allow).
 */
export default function ReleaseMaster() {
  const localUrl = useMemo(() => {
    const fname = 'PBPT RM - Master.pptx';
    return `${window.location.origin}/files/${encodeURIComponent(fname)}`;
  }, []);

  const officeEmbed = useMemo(() => {
    // Start on slide 1. Office handles the UI inside the iframe.
    return `https://view.officeapps.live.com/op/embed.aspx?src=${encodeURIComponent(localUrl)}&wdStartOn=1`;
  }, [localUrl]);

  return (
    <div style={{ height: '78vh', borderRadius: 12, overflow: 'hidden', background: '#0f162a' }}>
      {/* [PH1-F3] Embedded PPT */}
      <iframe
        title="PBPT RM - Master"
        src={officeEmbed}
        style={{ width: '100%', height: '100%', border: 0 }}
        allowFullScreen
      />
    </div>
  );
}
